namespace ghidra.app.plugin.core.decompile.actions;

using docking;
using docking.action;
using ghidra.app.actions;
using ghidra.app.decompiler;
using ghidra.app.decompiler.component;
using ghidra.app.plugin.core.decompile;
using ghidra.app.plugin.core.navigation.locationreferences;
using ghidra.app.util;
using ghidra.framework.plugintool;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.util;

public class FindReferencesToDataTypeAction : AbstractFindReferencesDataTypeAction {

	private DecompilerController controller;

	public FindReferencesToDataTypeAction(string owner, PluginTool tool,
			DecompilerController controller) : base(tool, NAME, owner, DEFAULT_KEY_STROKE)
    {
		this.controller = controller;

		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionFindUses"));
		setPopupMenuData(
			new MenuData(new string[] { LocationReferencesService.MENU_GROUP, "Find Uses of " }));
	}

	/* @Override */
	public DataType getDataType(ActionContext context) {
		return DecompilerUtils.getDataType((DecompilerActionContext) context);
	}

	/* @Override */
	protected string getDataTypeField(DataType dataType) {

		DecompilerPanel decompilerPanel = controller.getDecompilerPanel();
		ClangToken tokenAtCursor = decompilerPanel.getTokenAtCursor();
		if (tokenAtCursor is ClangFieldToken) {
			return tokenAtCursor.getText();
		}

		if (tokenAtCursor is ClangVariableToken) {

			if (dataType is Enum) {

				// check for enum field
				ClangVariableToken vt = (ClangVariableToken) tokenAtCursor;
				string text = vt.getText();
				Enum e = (Enum) dataType;
				string[] names = e.getNames();
				foreach (string name in names) {
					if (name.equals(text)) {
						return name;
					}
				}
			}
		}

		return null;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DecompilerActionContext)) {
			return false;
		}

		DataType dataType = getDataType(context);
		updateMenuName(dataType);
		return base.isEnabledForContext(context);
	}

	private void updateMenuName(DataType type) {

		if (type == null) {
			return; // not sure if this can happen
		}

		string typeName = type.getName();
		string menuName = "Find Uses of " + typeName;
		string fieldName = getDataTypeField(type);
		if (fieldName != null) {
			menuName += '.' + fieldName;
		}

		MenuData data = getPopupMenuData().cloneData();
		data.setMenuPath(new string[] { LocationReferencesService.MENU_GROUP, menuName });
		setPopupMenuData(data);
	}
}
